<?phpsession_start();// Check if user is logged inif (!isset($_SESSION['user_id'])) {    header("Location: login.php");    exit;}// Only admins and uploaders can upload documentsif (!in_array($_SESSION['role'], ['admin', 'uploader'])) {    header("Location: index.php");    exit;}if ($_SERVER['REQUEST_METHOD'] === 'POST' && isset($_FILES['document_files'])) {    $uploadDir = __DIR__ . '/uploads/documents/';    var_dump($uploadDir);    die("Zastaveno pro debug");    // Create documents directory if it doesn't exist    if (!is_dir($uploadDir)) {        mkdir($uploadDir, 0777, true);    }    $uploadedFiles = [];    $errors = [];    // Handle multiple file uploads    $files = $_FILES['document_files'];    $fileCount = count($files['name']);    for ($i = 0; $i < $fileCount; $i++) {        // Skip if no file or error        if ($files['error'][$i] !== UPLOAD_ERR_OK || empty($files['name'][$i])) {            continue;        }        $originalName = $files['name'][$i];        $tmpName = $files['tmp_name'][$i];        $fileSize = $files['size'][$i];        // Validate file type        $allowedExtensions = ['pdf', 'doc', 'docx', 'txt', 'xls', 'xlsx', 'ppt', 'pptx', 'jpg', 'jpeg', 'png', 'gif'];        $fileExtension = strtolower(pathinfo($originalName, PATHINFO_EXTENSION));        if (!in_array($fileExtension, $allowedExtensions)) {            $errors[] = "Nepodporovaný typ souboru: {$originalName}";            continue;        }        // Check file size (max 50MB)        if ($fileSize > 50 * 1024 * 1024) {            $errors[] = "Soubor {$originalName} je příliš velký (max 50MB)";            continue;        }        // Generate safe filename        $safeName = preg_replace('/[^a-zA-Z0-9-_.]/', '_', $originalName);        $safeName = time() . '_' . $i . '_' . $safeName;        $targetPath = $uploadDir . $safeName;        if (move_uploaded_file($tmpName, $targetPath)) {            $uploadedFiles[] = $originalName;        } else {            $errors[] = "Chyba při ukládání souboru: {$originalName}";        }    }    // Redirect with status    if (!empty($uploadedFiles) && empty($errors)) {        $message = "Úspěšně nahráno " . count($uploadedFiles) . " souborů";        header("Location: index.php#documents&status=success&message=" . urlencode($message));    } elseif (!empty($uploadedFiles) && !empty($errors)) {        $message = "Nahráno " . count($uploadedFiles) . " souborů, " . count($errors) . " chyb";        header("Location: index.php#documents&status=warning&message=" . urlencode($message));    } else {        $message = "Chyba: " . implode(', ', $errors);        header("Location: index.php#documents&status=error&message=" . urlencode($message));    }    exit;}echo "Neplatný požadavek.";?>